CREATE TABLE voice_clue_candidates (id VARCHAR(36) PRIMARY KEY, case_id VARCHAR(36) NOT NULL, voice_report_id VARCHAR(36) NULL, intercom_recording_id VARCHAR(36) NULL, submitted_by_user_id VARCHAR(36) NOT NULL, discoverer_user_id VARCHAR(36) NULL, source_type VARCHAR(40) NOT NULL, ai_generated BOOLEAN NOT NULL DEFAULT TRUE, transcript_text TEXT NULL, candidate_json TEXT NOT NULL, asr_version VARCHAR(100) NULL, model_version VARCHAR(100) NULL, status VARCHAR(20) NOT NULL, retry_count INT NOT NULL DEFAULT 0, failure_reason TEXT NULL, promoted_clue_id VARCHAR(36) NULL, created_at VARCHAR(40) NOT NULL, updated_at VARCHAR(40) NOT NULL, CONSTRAINT fk_voice_candidates_case FOREIGN KEY (case_id) REFERENCES cases(id) ON DELETE CASCADE, CONSTRAINT fk_voice_candidates_report FOREIGN KEY (voice_report_id) REFERENCES voice_reports(id) ON DELETE SET NULL, CONSTRAINT fk_voice_candidates_recording FOREIGN KEY (intercom_recording_id) REFERENCES intercom_recordings(id) ON DELETE SET NULL, CONSTRAINT fk_voice_candidates_submitter FOREIGN KEY (submitted_by_user_id) REFERENCES users(id), CONSTRAINT fk_voice_candidates_discoverer FOREIGN KEY (discoverer_user_id) REFERENCES users(id), CONSTRAINT fk_voice_candidates_clue FOREIGN KEY (promoted_clue_id) REFERENCES clues(id) ON DELETE SET NULL, CONSTRAINT chk_voice_candidates_status CHECK (status IN ('queued','processing','pending_review','confirmed','rejected','failed')));
-- statement-break
CREATE INDEX idx_voice_clue_candidates_case_status ON voice_clue_candidates(case_id, status, created_at);
